23	IMPOSSIBLE_TRAVEL_FLAG_30MIN_CARD	Impossible Travel Flag - 30 Minutes - Card	CARD	ALL	ATM	ROLLING	30MIN	NUMBER	Flag indicating impossible travel between ATM locations within 30 minutes (1 = true)	Y	2026-02-23 11:47:35.553278	CUSTOM	TRANSACTION	\nSELECT CASE\n    WHEN EXISTS (\n        SELECT 1\n        FROM efrm.transaction_master tm\n        WHERE tm.institution_id = $header.institutionId\n          AND tm.card_id = $transaction.cardId\n          AND tm.channel = 'ATM'\n          AND tm.txn_timestamp >= (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC') - INTERVAL '30 minutes'\n          AND tm.txn_timestamp < (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n          AND COALESCE(tm.source_txn_id, '') <> $transaction.sourceTxnId\n          AND COALESCE(NULLIF(tm.rule_engine_context #>> '{transaction,terminalId}', ''), '') <> ''\n          AND COALESCE(NULLIF(tm.rule_engine_context #>> '{transaction,terminalId}', ''), '') <> $transaction.terminalId\n    )\n    THEN 1\n    ELSE 0\nEND\n	2026-07-05 15:25:48.946704
27	DAYS_SINCE_CARD_ISSUED	Days Since Card Issued	CARD	ALL	ALL	POINT_IN_TIME	NA	NUMBER	Number of days since card issuance	Y	2026-02-23 14:19:50.006576	CUSTOM	TRANSACTION	\nSELECT COALESCE(\n    FLOOR(\n        EXTRACT(\n            EPOCH FROM (\n                (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n                - MIN(tm.txn_timestamp)\n            )\n        ) / 86400\n    ),\n    0\n)\nFROM efrm.transaction_master tm\nWHERE tm.institution_id = $header.institutionId\n  AND tm.card_id = $transaction.cardId\n  AND tm.txn_timestamp < (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n  AND COALESCE(tm.source_txn_id, '') <> $transaction.sourceTxnId\n	2026-07-05 15:25:48.946704
28	TXN_COUNT_24HOUR_CARD	Transaction Count - 24 Hours - Card	CARD	DEBIT	ATM	ROLLING	24HOUR	NUMBER	Number of ATM debit transactions on card within last 24 hours	Y	2026-02-23 14:20:01.857059	CUSTOM	TRANSACTION	\nSELECT COALESCE(COUNT(*), 0)\nFROM efrm.transaction_master tm\nWHERE tm.institution_id = $header.institutionId\n  AND tm.card_id = $transaction.cardId\n  AND tm.channel = 'ATM'\n  AND tm.txn_timestamp >= (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC') - INTERVAL '24 hours'\n  AND tm.txn_timestamp < (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n  AND COALESCE(tm.source_txn_id, '') <> $transaction.sourceTxnId\n  AND COALESCE(\n        NULLIF(tm.rule_engine_context #>> '{transaction,drCrIndicator}', ''),\n        CASE\n            WHEN UPPER(COALESCE(tm.txn_type, '')) IN ('WITHDRAWAL', 'PURCHASE', 'CASH', 'DEBIT', 'P2P', 'P2M', 'TRANSFER') THEN 'D'\n            WHEN UPPER(COALESCE(tm.txn_type, '')) IN ('REFUND', 'REVERSAL', 'CREDIT', 'DEPOSIT') THEN 'C'\n            ELSE NULL\n        END\n      ) = 'D'\n	2026-07-05 15:25:48.946704
30	DECLINE_COUNT_15MIN_CARD	Decline Count - 15 Minutes - Card	CARD	DEBIT	ATM	ROLLING	15MIN	NUMBER	Number of declined ATM transactions on card within last 15 minutes	Y	2026-02-23 14:26:51.840613	CUSTOM	TRANSACTION	\nSELECT COALESCE(COUNT(*), 0)\nFROM efrm.transaction_master tm\nWHERE tm.institution_id = $header.institutionId\n  AND tm.card_id = $transaction.cardId\n  AND tm.channel = 'ATM'\n  AND tm.txn_timestamp >= (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC') - INTERVAL '15 minutes'\n  AND tm.txn_timestamp < (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n  AND COALESCE(tm.source_txn_id, '') <> $transaction.sourceTxnId\n  AND UPPER(COALESCE(\n        NULLIF(tm.rule_engine_context #>> '{transaction,status}', ''),\n        CASE\n            WHEN COALESCE(NULLIF(tm.rule_engine_context #>> '{transaction,txnResponseCode}', ''), '') = '00' THEN 'SUCCESS'\n            WHEN COALESCE(NULLIF(tm.rule_engine_context #>> '{transaction,txnResponseCode}', ''), '') <> '' THEN 'FAILED'\n            ELSE NULL\n        END\n      )) = 'FAILED'\n	2026-07-05 15:25:48.946704
31	BIN_FRAUD_RATE_7D	BIN Fraud Rate - 7 Days	NETWORK	ALL	ALL	ROLLING	7DAY	PERCENTAGE	Fraud rate percentage at BIN level over last 7 days	Y	2026-02-23 15:17:00.952937	CUSTOM	TRANSACTION	\nSELECT COALESCE(\n    COUNT(*) FILTER (\n        WHERE EXISTS (\n            SELECT 1\n            FROM efrm.transaction_result tr\n            WHERE tr.transaction_master_id = tm.id\n              AND (\n                    COALESCE(tr.matched_rule_count, 0) > 0\n                 OR UPPER(COALESCE(tr.final_decision, '')) IN ('REVIEW', 'BLOCK', 'STEP_UP')\n                 OR UPPER(COALESCE(tr.is_alert_generated, 'N')) = 'Y'\n              )\n        )\n    )::numeric / NULLIF(COUNT(*), 0),\n    0\n)\nFROM efrm.transaction_master tm\nWHERE tm.institution_id = $header.institutionId\n  AND tm.source_system = $header.sourceSystem\n  AND LEFT(COALESCE(tm.card_id, ''), 6) = LEFT($transaction.cardId, 6)\n  AND tm.txn_timestamp >= (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC') - INTERVAL '7 days'\n  AND tm.txn_timestamp < (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n  AND COALESCE(tm.source_txn_id, '') <> $transaction.sourceTxnId\n	2026-07-05 15:25:48.946704
65	ECOM_CARD_TXN_COUNT_5MIN	ECOM Card Transaction Count 5 Minutes	CARD	BOTH	ECOM	ROLLING	5MIN	DECIMAL	Counts ECOM transactions for the same card in the last 5 minutes including the current transaction.	Y	2026-06-29 03:27:49.58866	CUSTOM	TRANSACTION	SELECT COUNT(*)::numeric AS ECOM_CARD_TXN_COUNT_5MIN\nFROM (\n  SELECT 1\n  FROM efrm.transaction_master t\n  WHERE t.institution_id = $header.institutionId\n    AND t.source_system = $header.sourceSystem\n    AND UPPER(COALESCE(t.channel, '')) = 'ECOM'\n    AND t.card_id = $transaction.cardId\n    AND COALESCE(t.txn_timestamp, t.created_at) >= CAST($transaction.txnTimestamp AS timestamp) - INTERVAL '5 minutes'\n    AND COALESCE(t.txn_timestamp, t.created_at) <= CAST($transaction.txnTimestamp AS timestamp)\n    AND COALESCE(t.source_txn_id, '') <> COALESCE($transaction.sourceTxnId, '')\n  UNION ALL\n  SELECT 1\n) s	2026-06-29 03:27:49.58866
