12	CUSTOMER_UTILIZATION_RATIO	Customer utilization ratio - 30 Days	CUSTOMER	BOTH	ALL	ROLLING	30DAY	AMOUNT	Total Utilization Ratio by Customer in last 30 Days	Y	2026-02-18 10:11:04.664471	CUSTOM	TRANSACTION	\nSELECT COALESCE(\n    CASE\n        WHEN x.credit_total = 0 THEN CASE WHEN x.debit_total > 0 THEN x.debit_total ELSE 0 END\n        ELSE x.debit_total / x.credit_total\n    END,\n    0\n)\nFROM (\n    SELECT\n        COALESCE(SUM(\n            CASE\n                WHEN COALESCE(\n                        NULLIF(tm.rule_engine_context #>> '{transaction,drCrIndicator}', ''),\n                        CASE\n                            WHEN UPPER(COALESCE(tm.txn_type, '')) IN ('WITHDRAWAL', 'PURCHASE', 'CASH', 'DEBIT', 'P2P', 'P2M', 'TRANSFER') THEN 'D'\n                            WHEN UPPER(COALESCE(tm.txn_type, '')) IN ('REFUND', 'REVERSAL', 'CREDIT', 'DEPOSIT') THEN 'C'\n                            ELSE NULL\n                        END\n                     ) = 'D'\n                THEN COALESCE(NULLIF(tm.rule_engine_context #>> '{transaction,drCrAmount}', '')::numeric, tm.txn_amount, 0)\n                ELSE 0\n            END\n        ), 0) AS debit_total,\n        COALESCE(SUM(\n            CASE\n                WHEN COALESCE(\n                        NULLIF(tm.rule_engine_context #>> '{transaction,drCrIndicator}', ''),\n                        CASE\n                            WHEN UPPER(COALESCE(tm.txn_type, '')) IN ('WITHDRAWAL', 'PURCHASE', 'CASH', 'DEBIT', 'P2P', 'P2M', 'TRANSFER') THEN 'D'\n                            WHEN UPPER(COALESCE(tm.txn_type, '')) IN ('REFUND', 'REVERSAL', 'CREDIT', 'DEPOSIT') THEN 'C'\n                            ELSE NULL\n                        END\n                     ) = 'C'\n                THEN COALESCE(NULLIF(tm.rule_engine_context #>> '{transaction,drCrAmount}', '')::numeric, tm.txn_amount, 0)\n                ELSE 0\n            END\n        ), 0) AS credit_total\n    FROM efrm.transaction_master tm\n    WHERE tm.institution_id = $header.institutionId\n      AND tm.source_system = $header.sourceSystem\n      AND tm.customer_id = $entity.customerId\n      AND tm.txn_timestamp >= (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC') - INTERVAL '30 days'\n      AND tm.txn_timestamp < (CAST($transaction.txnTimestamp AS timestamptz) AT TIME ZONE 'UTC')\n      AND COALESCE(tm.source_txn_id, '') <> $transaction.sourceTxnId\n) x\n	2026-07-05 15:25:48.946704
